type AgentServiceHTTPClient interface {
	// ArchiveAgentSessions 归档 / 取消归档（还在运行或等待批准的不能归档）
	ArchiveAgentSessions(ctx context.Context, req *ArchiveAgentSessionsRequest, opts ...http.CallOption) (rsp *ArchiveAgentSessionsResponse, err error)
	// BrowseAgentWorkspace 「查看文件」：只读地列出工作区里的目录和文件
	BrowseAgentWorkspace(ctx context.Context, req *BrowseAgentWorkspaceRequest, opts ...http.CallOption) (rsp *BrowseAgentWorkspaceResponse, err error)
	// CancelAgentSession 停止当前这一轮
	CancelAgentSession(ctx context.Context, req *CancelAgentSessionRequest, opts ...http.CallOption) (rsp *CancelAgentSessionResponse, err error)
	// CreateAgentDir 新建文件夹
	CreateAgentDir(ctx context.Context, req *CreateAgentDirRequest, opts ...http.CallOption) (rsp *CreateAgentDirResponse, err error)
	CreateAgentMcpServer(ctx context.Context, req *CreateAgentMcpServerRequest, opts ...http.CallOption) (rsp *CreateAgentMcpServerResponse, err error)
	// CreateAgentProvider 第三方接口
	CreateAgentProvider(ctx context.Context, req *CreateAgentProviderRequest, opts ...http.CallOption) (rsp *CreateAgentProviderResponse, err error)
	// CreateAgentRuntime 添加其它 ACP Agent
	CreateAgentRuntime(ctx context.Context, req *CreateAgentRuntimeRequest, opts ...http.CallOption) (rsp *CreateAgentRuntimeResponse, err error)
	// CreateAgentSession 新建会话并发出第一条消息
	CreateAgentSession(ctx context.Context, req *CreateAgentSessionRequest, opts ...http.CallOption) (rsp *CreateAgentSessionResponse, err error)
	CreateAgentSkill(ctx context.Context, req *CreateAgentSkillRequest, opts ...http.CallOption) (rsp *CreateAgentSkillResponse, err error)
	CreateAgentWorkspace(ctx context.Context, req *CreateAgentWorkspaceRequest, opts ...http.CallOption) (rsp *CreateAgentWorkspaceResponse, err error)
	// DeleteAgentFiles 删除文件或文件夹（整个删掉，不进回收站）
	DeleteAgentFiles(ctx context.Context, req *DeleteAgentFilesRequest, opts ...http.CallOption) (rsp *DeleteAgentFilesResponse, err error)
	DeleteAgentMcpServer(ctx context.Context, req *DeleteAgentMcpServerRequest, opts ...http.CallOption) (rsp *DeleteAgentMcpServerResponse, err error)
	DeleteAgentProvider(ctx context.Context, req *DeleteAgentProviderRequest, opts ...http.CallOption) (rsp *DeleteAgentProviderResponse, err error)
	// DeleteAgentQueuedPrompt 撤回一条排着队的消息（还没发出去的）
	DeleteAgentQueuedPrompt(ctx context.Context, req *DeleteAgentQueuedPromptRequest, opts ...http.CallOption) (rsp *DeleteAgentQueuedPromptResponse, err error)
	DeleteAgentRuntime(ctx context.Context, req *DeleteAgentRuntimeRequest, opts ...http.CallOption) (rsp *DeleteAgentRuntimeResponse, err error)
	DeleteAgentSessions(ctx context.Context, req *DeleteAgentSessionsRequest, opts ...http.CallOption) (rsp *DeleteAgentSessionsResponse, err error)
	DeleteAgentSkill(ctx context.Context, req *DeleteAgentSkillRequest, opts ...http.CallOption) (rsp *DeleteAgentSkillResponse, err error)
	// DeleteAgentWorkspace 移除工作区：只删记录，目录里的文件不动
	DeleteAgentWorkspace(ctx context.Context, req *DeleteAgentWorkspaceRequest, opts ...http.CallOption) (rsp *DeleteAgentWorkspaceResponse, err error)
	// DetachAgentSession 把复刻出来的会话移到外层
	DetachAgentSession(ctx context.Context, req *DetachAgentSessionRequest, opts ...http.CallOption) (rsp *DetachAgentSessionResponse, err error)
	// DetectAgentRuntime 重新检测
	DetectAgentRuntime(ctx context.Context, req *DetectAgentRuntimeRequest, opts ...http.CallOption) (rsp *DetectAgentRuntimeResponse, err error)
	// ExportAgentSessions 导出记录：返回会话的全部事件，由页面排版成 Markdown 下载
	ExportAgentSessions(ctx context.Context, req *ExportAgentSessionsRequest, opts ...http.CallOption) (rsp *ExportAgentSessionsResponse, err error)
	// FetchAgentProviderModels 获取可用模型
	FetchAgentProviderModels(ctx context.Context, req *FetchAgentProviderModelsRequest, opts ...http.CallOption) (rsp *FetchAgentProviderModelsResponse, err error)
	// ForkAgentSession 复刻对话；worktree 为 true 时放到自动命名的新工作树里
	ForkAgentSession(ctx context.Context, req *ForkAgentSessionRequest, opts ...http.CallOption) (rsp *ForkAgentSessionResponse, err error)
	// GetAgentDocs 项目指令文件（AGENTS.md / CLAUDE.md）；按目录读，新建工作区时目录还没有记录
	GetAgentDocs(ctx context.Context, req *GetAgentDocsRequest, opts ...http.CallOption) (rsp *GetAgentDocsResponse, err error)
	// GetAgentFileRaw 原样读一个文件（预览图片，Markdown 里用到的图片）
	GetAgentFileRaw(ctx context.Context, req *GetAgentFileRawRequest, opts ...http.CallOption) (rsp *GetAgentSessionUploadResponse, err error)
	// GetAgentNotify —— 通知 ——
	GetAgentNotify(ctx context.Context, req *GetAgentNotifyRequest, opts ...http.CallOption) (rsp *GetAgentNotifyResponse, err error)
	// GetAgentOptions —— 选择器 ——
	// 新会话 / 会话里 / 工作区默认值用的选项：每个 Agent 的供应商、模型、推理强度和权限模式
	GetAgentOptions(ctx context.Context, req *GetAgentOptionsRequest, opts ...http.CallOption) (rsp *GetAgentOptionsResponse, err error)
	// GetAgentOverview 各管理标签的数量：自己的会话、工作区、MCP、技能，加上大家共用的供应商、运行时、通知
	GetAgentOverview(ctx context.Context, req *GetAgentOverviewRequest, opts ...http.CallOption) (rsp *GetAgentOverviewResponse, err error)
	// GetAgentPreviewToken HTML 预览的签名：iframe 按 /api/v1/public/agent/preview/{节点}/{签名}/{相对路径} 把目录当静态站点加载
	GetAgentPreviewToken(ctx context.Context, req *GetAgentPreviewTokenRequest, opts ...http.CallOption) (rsp *GetAgentPreviewTokenResponse, err error)
	// GetAgentProviderBalance 账户余额：只有能查余额的供应商类型（AgentVendor.balance）才有
	GetAgentProviderBalance(ctx context.Context, req *GetAgentProviderBalanceRequest, opts ...http.CallOption) (rsp *GetAgentProviderBalanceResponse, err error)
	GetAgentSession(ctx context.Context, req *GetAgentSessionRequest, opts ...http.CallOption) (rsp *GetAgentSessionResponse, err error)
	// GetAgentSessionChanges 右侧「改动」：会话目录相对当前分支的未提交改动
	GetAgentSessionChanges(ctx context.Context, req *GetAgentSessionChangesRequest, opts ...http.CallOption) (rsp *GetAgentSessionChangesResponse, err error)
	// GetAgentSessionProcess 会话的 Agent 进程（命令、进程号、内存、已运行），展开看时才读
	GetAgentSessionProcess(ctx context.Context, req *GetAgentSessionProcessRequest, opts ...http.CallOption) (rsp *GetAgentSessionProcessResponse, err error)
	// GetAgentSessionUpload 取回消息里上传过的附件（显示图片）
	GetAgentSessionUpload(ctx context.Context, req *GetAgentSessionUploadRequest, opts ...http.CallOption) (rsp *GetAgentSessionUploadResponse, err error)
	// GetAgentSidebar —— 会话 ——
	// 会话栏：我的未归档会话，按工作区分层
	GetAgentSidebar(ctx context.Context, req *GetAgentSidebarRequest, opts ...http.CallOption) (rsp *GetAgentSidebarResponse, err error)
	GetAgentSkill(ctx context.Context, req *GetAgentSkillRequest, opts ...http.CallOption) (rsp *GetAgentSkillResponse, err error)
	// ImportAgentMcpServers 粘贴 mcpServers JSON 导入
	ImportAgentMcpServers(ctx context.Context, req *ImportAgentMcpServersRequest, opts ...http.CallOption) (rsp *ImportAgentMcpServersResponse, err error)
	// ImportAgentSkill 导入：压缩包（zip 内容）、Git 地址、服务器上已有的目录
	ImportAgentSkill(ctx context.Context, req *ImportAgentSkillRequest, opts ...http.CallOption) (rsp *ImportAgentSkillResponse, err error)
	// ListAgentDirs 「浏览」：列出服务器上某个目录下的子目录
	ListAgentDirs(ctx context.Context, req *ListAgentDirsRequest, opts ...http.CallOption) (rsp *ListAgentDirsResponse, err error)
	// ListAgentMcpServers —— MCP ——
	ListAgentMcpServers(ctx context.Context, req *ListAgentMcpServersRequest, opts ...http.CallOption) (rsp *ListAgentMcpServersResponse, err error)
	// ListAgentProviders —— 模型供应商 ——
	ListAgentProviders(ctx context.Context, req *ListAgentProvidersRequest, opts ...http.CallOption) (rsp *ListAgentProvidersResponse, err error)
	// ListAgentRuntimes —— 运行时 ——
	ListAgentRuntimes(ctx context.Context, req *ListAgentRuntimesRequest, opts ...http.CallOption) (rsp *ListAgentRuntimesResponse, err error)
	// ListAgentSessionFiles 右侧「文件」：按目录懒加载
	ListAgentSessionFiles(ctx context.Context, req *ListAgentSessionFilesRequest, opts ...http.CallOption) (rsp *ListAgentSessionFilesResponse, err error)
	// ListAgentSessions 会话列表（管理页）：状态筛选、标题搜索、分页，都在 SQL 里完成；只有自己的，all 为 true 时是所有人的（全员 Agent 页）
	ListAgentSessions(ctx context.Context, req *ListAgentSessionsRequest, opts ...http.CallOption) (rsp *ListAgentSessionsResponse, err error)
	// ListAgentSkills —— 技能 ——
	ListAgentSkills(ctx context.Context, req *ListAgentSkillsRequest, opts ...http.CallOption) (rsp *ListAgentSkillsResponse, err error)
	// ListAgentWorkspaces —— 工作区 ——
	ListAgentWorkspaces(ctx context.Context, req *ListAgentWorkspacesRequest, opts ...http.CallOption) (rsp *ListAgentWorkspacesResponse, err error)
	// MoveAgentFile 改名或挪到另一个文件夹
	MoveAgentFile(ctx context.Context, req *MoveAgentFileRequest, opts ...http.CallOption) (rsp *MoveAgentFileResponse, err error)
	// PromptAgentSession 发一条消息，开始新的一轮；立刻返回，后续靠 WebSocket
	PromptAgentSession(ctx context.Context, req *PromptAgentSessionRequest, opts ...http.CallOption) (rsp *PromptAgentSessionResponse, err error)
	// PurgeAgentSessions 删除全部归档会话
	PurgeAgentSessions(ctx context.Context, req *PurgeAgentSessionsRequest, opts ...http.CallOption) (rsp *PurgeAgentSessionsResponse, err error)
	// ReadAgentSessionFile 打开文件（只读）
	ReadAgentSessionFile(ctx context.Context, req *ReadAgentSessionFileRequest, opts ...http.CallOption) (rsp *ReadAgentSessionFileResponse, err error)
	// ReadAgentWorkspaceFile 新会话页里打开工作区的文件（只读，和会话里打开文件一样的返回）
	ReadAgentWorkspaceFile(ctx context.Context, req *ReadAgentWorkspaceFileRequest, opts ...http.CallOption) (rsp *ReadAgentSessionFileResponse, err error)
	RenameAgentSession(ctx context.Context, req *RenameAgentSessionRequest, opts ...http.CallOption) (rsp *RenameAgentSessionResponse, err error)
	// ResolveAgentPermission 回答批准卡片
	ResolveAgentPermission(ctx context.Context, req *ResolveAgentPermissionRequest, opts ...http.CallOption) (rsp *ResolveAgentPermissionResponse, err error)
	// RevertAgentSessionFile 撤销某个文件的改动
	RevertAgentSessionFile(ctx context.Context, req *RevertAgentSessionFileRequest, opts ...http.CallOption) (rsp *RevertAgentSessionFileResponse, err error)
	// SaveAgentFile —— 文件树里的编辑：有会话按会话目录，新会话页还没有会话时按工作区（和 @ 搜索一样给 session_id 或 workspace_id）——
	// 保存文本文件：编辑后保存，或者新建一个文件
	SaveAgentFile(ctx context.Context, req *SaveAgentFileRequest, opts ...http.CallOption) (rsp *SaveAgentFileResponse, err error)
	// SaveAgentNotifyChannel 保存某种通知方式的配置，保存后自动启用
	SaveAgentNotifyChannel(ctx context.Context, req *SaveAgentNotifyChannelRequest, opts ...http.CallOption) (rsp *SaveAgentNotifyChannelResponse, err error)
	// SearchAgentFiles @ 引用文件：按文件名搜索会话目录（新会话还没有会话时按工作区搜）
	SearchAgentFiles(ctx context.Context, req *SearchAgentFilesRequest, opts ...http.CallOption) (rsp *SearchAgentFilesResponse, err error)
	// SendAgentQueuedPrompt 排着队的一条马上发：能插进正在跑的一轮就插进去（ACP v2）；插不进去的停下这一轮，让它作为下一轮发出
	SendAgentQueuedPrompt(ctx context.Context, req *SendAgentQueuedPromptRequest, opts ...http.CallOption) (rsp *SendAgentQueuedPromptResponse, err error)
	// SetAgentMcpDefault 新会话默认开启的开关
	SetAgentMcpDefault(ctx context.Context, req *SetAgentMcpDefaultRequest, opts ...http.CallOption) (rsp *SetAgentMcpDefaultResponse, err error)
	SetAgentNotifyChannelEnabled(ctx context.Context, req *SetAgentNotifyChannelEnabledRequest, opts ...http.CallOption) (rsp *SetAgentNotifyChannelEnabledResponse, err error)
	// SetAgentRuntimeMode 安装方式：Momoko 下载并更新 / 用服务器上已有的命令
	SetAgentRuntimeMode(ctx context.Context, req *SetAgentRuntimeModeRequest, opts ...http.CallOption) (rsp *SetAgentRuntimeModeResponse, err error)
	// SetAgentRuntimeModels 服务器上的登录：给检查时读到的模型设最长上下文和最长输出
	SetAgentRuntimeModels(ctx context.Context, req *SetAgentRuntimeModelsRequest, opts ...http.CallOption) (rsp *SetAgentRuntimeModelsResponse, err error)
	// SetAgentSessionOption 切换权限模式 / 模型 / 推理强度
	SetAgentSessionOption(ctx context.Context, req *SetAgentSessionOptionRequest, opts ...http.CallOption) (rsp *SetAgentSessionOptionResponse, err error)
	SetAgentSkillEnabled(ctx context.Context, req *SetAgentSkillEnabledRequest, opts ...http.CallOption) (rsp *SetAgentSkillEnabledResponse, err error)
	// StopAgentSessionItem 只停一项（ACP v2，它声明了能单独停时）：一个工具调用，或者一个子 Agent
	StopAgentSessionItem(ctx context.Context, req *StopAgentSessionItemRequest, opts ...http.CallOption) (rsp *StopAgentSessionItemResponse, err error)
	// TestAgentMcpServer 测试连接：由 Momoko 自己连一次，读它的工具列表
	TestAgentMcpServer(ctx context.Context, req *TestAgentMcpServerRequest, opts ...http.CallOption) (rsp *TestAgentMcpServerResponse, err error)
	// TestAgentNotifyChannel 发一条测试；fields 为空时用已保存的配置
	TestAgentNotifyChannel(ctx context.Context, req *TestAgentNotifyChannelRequest, opts ...http.CallOption) (rsp *TestAgentNotifyChannelResponse, err error)
	// TestAgentProvider 测试：用主模型发一条消息，供应商给的每种协议各发一次。有草稿测草稿（地址、密钥留空且有 id 时用已保存的），否则测已保存的
	TestAgentProvider(ctx context.Context, req *TestAgentProviderRequest, opts ...http.CallOption) (rsp *TestAgentProviderResponse, err error)
	UpdateAgentMcpServer(ctx context.Context, req *UpdateAgentMcpServerRequest, opts ...http.CallOption) (rsp *UpdateAgentMcpServerResponse, err error)
	// UpdateAgentNotifyEvents 三个时机开关
	UpdateAgentNotifyEvents(ctx context.Context, req *UpdateAgentNotifyEventsRequest, opts ...http.CallOption) (rsp *UpdateAgentNotifyEventsResponse, err error)
	UpdateAgentProvider(ctx context.Context, req *UpdateAgentProviderRequest, opts ...http.CallOption) (rsp *UpdateAgentProviderResponse, err error)
	// UpdateAgentRunSettings 同时运行的进程上限、空闲后结束进程
	UpdateAgentRunSettings(ctx context.Context, req *UpdateAgentRunSettingsRequest, opts ...http.CallOption) (rsp *UpdateAgentRunSettingsResponse, err error)
	// UpdateAgentRuntime 检查更新；由 Momoko 下载的会直接更新到最新版本
	UpdateAgentRuntime(ctx context.Context, req *UpdateAgentRuntimeRequest, opts ...http.CallOption) (rsp *UpdateAgentRuntimeResponse, err error)
	UpdateAgentSkill(ctx context.Context, req *UpdateAgentSkillRequest, opts ...http.CallOption) (rsp *UpdateAgentSkillResponse, err error)
	UpdateAgentWorkspace(ctx context.Context, req *UpdateAgentWorkspaceRequest, opts ...http.CallOption) (rsp *UpdateAgentWorkspaceResponse, err error)
}

